INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(37411, 'Isaiah 63:7', 'Isaiah', 63, 7, 'زه به وکړمه بیان د څښتن د تلپاتې مینې د ستاینې وړ دي د څښتن کارونه ډېر برکت ورکړی هغه خپل د اسراییلو قوم ته په خاطر د خپل رحم او تلپاتې مینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_7.mp3', '', 1761754199, 1761754199),
(37412, 'Isaiah 63:8', 'Isaiah', 63, 8, 'څښتن وویل: «په رښتیا هغوی زما قوم دی او زما سره به خیانت ونه کړي.» نو څښتن د هغوی ژغورونکی شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_8.mp3', '', 1761754199, 1761754199),
(37413, 'Isaiah 63:9', 'Isaiah', 63, 9, 'د هغوی په ټولو کړاوونو کې څښتن هم شریک شو او هغه فرښته چې د هغه په حضور کې ده، هغوی یې وژغورل. هغوی یې د خپلې مینې او خواخوږۍ له مخې وژغورل. هغه پخوا هم تل په هغوی باندې پام کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_9.mp3', '', 1761754199, 1761754199),
(37414, 'Isaiah 63:10', 'Isaiah', 63, 10, 'خو هغوی د څښتن په وړاندې سرغړونه وکړه او د هغه سپېڅلی روح یې خفه کړ. نو ځکه هغه د هغوی دښمن شو او په خپله یې ورسره جګړه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_10.mp3', '', 1761754199, 1761754199),
(37415, 'Isaiah 63:11', 'Isaiah', 63, 11, 'بیا هغوی هغه تېره زمانه را په یاد کړه چې څنګه موسی خپل خلک د مصر څخه وویستل او پوښتنه یې وکړه: «چېرته دی هغه کس چې د اسراییلو قوم یې د هغوی له مشرانو سره له سرې بحیرې نه تېر کړل؟ چېرته دی هغه څښتن چې هغوی ته یې خپل سپېڅلی روح نازل کړ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_11.mp3', '', 1761754199, 1761754199),
(37416, 'Isaiah 63:12', 'Isaiah', 63, 12, 'په خپل ستر قدرت یې د موسی په لاس لوی کارونه تر سره کړل. هغه د بحیرې اوبه په منځ کې سره بېلې کړې او نوم یې تلپاتې شهرت وموند.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_12.mp3', '', 1761754199, 1761754199),
(37417, 'Isaiah 63:13', 'Isaiah', 63, 13, 'څښتن د بحیرې څخه د تېرېدو په وخت کې د اسراییلو قوم ته لارښوونه وکړه. هغوی لکه د اسونو په شان پرته له تیندک خوړلو په دښته کې روان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_13.mp3', '', 1761754199, 1761754199),
(37418, 'Isaiah 63:14', 'Isaiah', 63, 14, 'لکه څنګه چې څاروي په یوه ارامه دره کې روان وي، نو د څښتن روح هغوی ته همداسې ارامي ورکړه. په دې ډول څښتن خپل قوم ته لارښوونه وکړه او د هغه نوم د دې کار په خاطر جلال وموند.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_14.mp3', '', 1761754199, 1761754199),
(37419, 'Isaiah 63:15', 'Isaiah', 63, 15, 'ای څښتنه، د اسمان نه لاندې وګوره، د خپل سپېڅلي او د جلال نه ډک استوګنځي څخه په مونږ باندې نظر وکړه. چېرته دی ستا غیرت او قدرت؟ چېرته ده هغه مینه او رحم چې زمونږ سره دې درلودله؟ ولې یې له مونږه سپموې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_15.mp3', '', 1761754199, 1761754199),
(37420, 'Isaiah 63:16', 'Isaiah', 63, 16, 'ځکه ته زمونږ پلار یې. که څه هم زمونږ نیکونه ابراهیم او یعقوب مونږ خپل نه ګڼي. خو ای څښتنه، ته زمونږ پلار یې، چې له پخوا څخه زمونږ ژغورونکی یې او ستا شهرت له پخوا نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_16.mp3', '', 1761754199, 1761754199),
(37421, 'Isaiah 63:17', 'Isaiah', 63, 17, 'ای څښتنه! ولې مونږ پرېږدې چې ستا د لارې څخه وګرځو؟ ولې زمونږ زړونه دومره سختوې چې ستا څخه ونه وېرېږو؟ د خپلو خدمتګارانو او هغو قبیلو په خاطر چې تل ستا دي، بېرته مونږ ته راوګرځه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_17.mp3', '', 1761754199, 1761754199),
(37422, 'Isaiah 63:18', 'Isaiah', 63, 18, 'ستا سپېڅلی ځای د لږ وخت دپاره ستا د سپېڅلو خلکو سره ؤ، خو وروسته دښمنانو هغه ځای تر پښو لاندې کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_18.mp3', '', 1761754199, 1761754199),
(37423, 'Isaiah 63:19', 'Isaiah', 63, 19, 'مونږ د هغو خلکو په څېر شو چې ګواکې هېڅکله دې په هغوی واکمني نه وه کړې او هېڅکله ستا په نامه نه یادېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_19.mp3', '', 1761754199, 1761754199),
(37424, 'Daniel 11:1', 'Daniel', 11, 1, 'او د داريوس ميدى د بادشاهۍ په اول کال، زۀ ودرېدلم چې هغه مضبوط او تکړه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_1.mp3', '', 1761754199, 1761754199),
(37425, 'Daniel 11:2', 'Daniel', 11, 2, 'نو بيا اوس، زۀ تاسو ته رښتيا وايم. د قومونو په خپلو کښې جنګونه په فارس کښې به نور درې بادشاهان راوچت شى، او بيا به څلورم بادشاه راشى، څوک چې به د هغوئ ټولو نه زيات مالداره وى. هغۀ د خپل دولت په ذريعه طاقت حاصل کړے دے، نو هغه به هر څوک د يونان د حکومت په خلاف راوچت کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_2.mp3', '', 1761754199, 1761754199),
(37426, 'Daniel 11:3', 'Daniel', 11, 3, 'نو بيا به يو زورَور بادشاه راشى او هغه به په لوئ اختيار سره بادشاهى کوى او هر څۀ چې يې زړۀ غواړى هغه به وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_3.mp3', '', 1761754199, 1761754199),
(37427, 'Daniel 11:4', 'Daniel', 11, 4, 'خو د هغۀ د ښکاره کېدو نه وروستو به د هغۀ بادشاهى ټوکړې ټوکړې شى، او دا به په څلورو حِصو تقسيم شى. دا به د دۀ اولاد ته پاتې نۀ شى، او نۀ به بيا هغه داسې طاقتوره وى لکه څنګه چې اول وه، ځکه د دۀ بادشاهى به د بېخ نه ختمه شى او نورو ته به حواله کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_4.mp3', '', 1761754199, 1761754199),
(37428, 'Daniel 11:5', 'Daniel', 11, 5, 'د جنوب بادشاه به مضبوط شى، خو د هغۀ يو آفسر به د هغۀ نه زيات مضبوط شى او هغه به د هغۀ نه په زيات طاقت سره په خپلو خلقو حکومت کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_5.mp3', '', 1761754199, 1761754199),
(37429, 'Daniel 11:6', 'Daniel', 11, 6, 'څو کاله پس به د جنوب او د شمال بادشاه په خپلو کښې اِتحاد جوړ کړى. د جنوب د بادشاه لور به د شمال بادشاه ته د اِتحاد جوړولو دپاره وادۀ کړے شى، خو هغه به په خپل خاوند اثر رسوخ ونۀ ساتلے شى هغه او د هغې اثر رسوخ به ختم شى. نو هغه به بيا سره د خپل پلار او شاهى خِدمت کوونکو ووژلے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_6.mp3', '', 1761754199, 1761754199),
(37430, 'Daniel 11:7', 'Daniel', 11, 7, 'نو بيا به د هغې د خاندان نه يو کس راوچت شى چې د هغې ځائ ونيسى. او هغه به د شمال د بادشاه په فوج حمله وکړى او هغه قلعه ګانو ته به ننوځى، هغه به د هغوئ خلاف جنګ وکړى او کامياب به شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_7.mp3', '', 1761754199, 1761754199),
(37431, 'Daniel 11:8', 'Daniel', 11, 8, 'هغه به د هغوئ معبودان، د هغوئ د پيتلو بُتان او د هغوئ قيمتى د سپينو او سرو زرو سامان قبضه کړى او ځان سره به يې مِصر ته يوسى. او د څو کالو پورې به هغه د شمال په بادشاه حمله ونۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_8.mp3', '', 1761754199, 1761754199),
(37432, 'Daniel 11:9', 'Daniel', 11, 9, 'بيا به د شمال بادشاه د جنوب د بادشاه په سلطنت حمله وکړى خو هغه به واپس شى او خپل مُلک ته به لاړ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_9.mp3', '', 1761754199, 1761754199),
(37433, 'Daniel 11:10', 'Daniel', 11, 10, 'د هغۀ زامن به د جنګ دپاره تيار شى او يو لوئ لښکر به جوړ کړى، دا به لکه د سېلاب غوندې وى او جنګ به د هغۀ قلعه ګانو ته ورورسوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_10.mp3', '', 1761754199, 1761754199),
(37434, 'Daniel 11:11', 'Daniel', 11, 11, 'بيا به د جنوب بادشاه په غصه کښې راوځى او د شمال د بادشاه په خلاف به جنګ وکړى، څوک چې به لوئ لښکر تيار کړى خو هغوئ به هم شکست وخورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_11.mp3', '', 1761754199, 1761754199),
(37435, 'Daniel 11:12', 'Daniel', 11, 12, 'کله چې فوج تباه شى نو د جنوب بادشاه کښې به غرور راشى او هغه به په زرګونو خلق مړۀ کړى، خو هغه به د ډېر وخت پورې کامياب نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_12.mp3', '', 1761754199, 1761754199),
(37436, 'Daniel 11:13', 'Daniel', 11, 13, 'ځکه چې د شمال بادشاه به بل لښکر راغونډ کړى، د وړومبى لښکر نه به غټ وى، او يو څو کاله پس به هغه د يو لوئ لښکر سره په هر قسمه وسلو سمبال راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_13.mp3', '', 1761754199, 1761754199),
(37437, 'Daniel 11:14', 'Daniel', 11, 14, 'په هغه وخت کښې به ډېر خلق د جنوب د بادشاه خلاف راپاڅى. ستا د قوم پارېدلى خلق به د رويا په پوره کېدو کښې بغاوت وکړى، خو هغوئ به کامياب نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_14.mp3', '', 1761754199, 1761754199),
(37438, 'Daniel 11:15', 'Daniel', 11, 15, 'نو بيا به د شمال بادشاه راشى او قلعه بند ښار د قبضه کولو دپاره به د خاورو ډيرى جوړ کړى. د جنوب فوجيان به دوئ ايسارولے نۀ شى، تر دې چې د ټولو نه ښۀ او زورَور فوجيان به هم د هغوئ مقابله نۀ شى کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_15.mp3', '', 1761754199, 1761754199),
(37439, 'Daniel 11:16', 'Daniel', 11, 16, 'حمله کوونکے بادشاه به هم هغه څۀ کوى څۀ چې يې زړۀ غواړى، څوک به د هغۀ خلاف نۀ شى ودرېدلے. هغه به ځان په ښائسته مُلک کښې آباد کړى او هغۀ سره به د هغې د تباه کولو اختيار وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_16.mp3', '', 1761754199, 1761754199),
(37440, 'Daniel 11:17', 'Daniel', 11, 17, 'هغه به يوه منصوبه جوړه کړى چې د خپل ټول سلطنت د زور سره راشى او هغه به د جنوب د بادشاه سره اِتحاد وکړى. او خپله لور به هغۀ ته وادۀ کړى د دې دپاره چې سلطنت تباه کړى، خو د هغۀ منصوبه به کاميابه نۀ شى او نۀ به فائده ورکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_17.mp3', '', 1761754199, 1761754199),
(37441, 'Daniel 11:18', 'Daniel', 11, 18, 'هغه به ساحلى علاقې خوا ته خپله توجو وګرځوى او په ډېرو علاقو به قبضه وکړى، خو د يو بل مُلک فوجى کمانډر به د هغۀ ګستاخانه رويه ختمه کړى او په شرمونو به يې وشرموى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_18.mp3', '', 1761754199, 1761754199),
(37442, 'Daniel 11:19', 'Daniel', 11, 19, 'د دې نه پس به هغه خپل مُلک کښې خپلو قلعه ګانو ته واپس شى خو هغه به تيندک وخورى او وبه غورزيږى نو د هغۀ نام و نشان به پاتې نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_19.mp3', '', 1761754199, 1761754199),
(37443, 'Daniel 11:20', 'Daniel', 11, 20, 'د هغۀ په ځائ به بل بادشاه راشى هغه به محصُول اخستونکى ولېږى چې شاهى شان و شوکت پرې وساتى. خو په لږو ورځو کښې به هغه تباه شى، خو نۀ د غصې په وجه او نۀ د جنګ په وجه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_20.mp3', '', 1761754199, 1761754199),
(37444, 'Daniel 11:21', 'Daniel', 11, 21, 'د هغۀ په ځائ به يو بدعمله سړے بادشاه شى چې د بادشاهۍ حق به ورته نۀ وى حاصل. هغه به ناګهانه راښکاره شى، او په سلطنت به حمله وکړى، په چالاکۍ او ټګۍ سره به بادشاهۍ قبضه کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_21.mp3', '', 1761754199, 1761754199),
(37445, 'Daniel 11:22', 'Daniel', 11, 22, 'د هغۀ په وړاندې به لوئ لښکر جارُو شى، هغه او مشر اِمام به تباه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_22.mp3', '', 1761754199, 1761754199),
(37446, 'Daniel 11:23', 'Daniel', 11, 23, 'هغۀ سره د لوظ کولو نه پس به هغه د هغوئ سره دوکه وکړى او د لږو کسانو سره به هغه قدرت حاصل کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_23.mp3', '', 1761754199, 1761754199),
(37447, 'Daniel 11:24', 'Daniel', 11, 24, 'ناګهانه به مالداره صوبې ونيسى نو هغه به په هغوئ حمله وکړى او هغه هر څۀ به حاصل کړى چې د هغوئ پلار نيکۀ نۀ وو حاصل کړى. هغه به غنيمت، لوټ شوے دولت په خپلو ملګرو کښې تقسيم کړى. هغه به د قلعه ګانو د قبضه کولو منصوبې جوړې کړى خو دا به د لږ وخت دپاره وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_24.mp3', '', 1761754199, 1761754199),
(37448, 'Daniel 11:25', 'Daniel', 11, 25, 'د يو لوئ لښکر سره به هغه زور ولګوى او په نرتوب به د جنوب بادشاه په خلاف جنګ وکړى. د جنوب بادشاه به هم د خپل لوئ او طاقتور لښکر سره جنګ وکړى، خو هغه به د شمال د بادشاه په وړاندې د هغه منصوبو په وجه ونۀ دريږى کومې يې چې د هغۀ په خلاف جوړې کړې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_25.mp3', '', 1761754199, 1761754199),
(37449, 'Daniel 11:26', 'Daniel', 11, 26, 'هغوئ څوک چې د بادشاه روټۍ خورى هغوئ به د هغۀ د تباه کولو کوشش وکړى، د هغۀ لښکر به ختم شى، او ډېر به په جنګ کښې مړۀ کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_26.mp3', '', 1761754199, 1761754199),
(37450, 'Daniel 11:27', 'Daniel', 11, 27, 'نو دواړه بادشاهان به د شېطانۍ نه ډکو زړونو سره په يو مېز کښېنى او يو بل ته به دروغ ووائى، خو يو به هم کامياب نۀ شى ځکه چې خاتمه به بيا هم په خپل مقرر وخت راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_27.mp3', '', 1761754199, 1761754199),
(37451, 'Daniel 11:28', 'Daniel', 11, 28, 'د شمال بادشاه به ډېر دولت سره خپل مُلک ته واپس شى، خو د هغۀ زړۀ به د مقدس لوظ خلاف شى. هغه به دې ته نقصان ورسوى او بيا به خپل مُلک ته واپس لاړ شى. ‏', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_28.mp3', '', 1761754199, 1761754199),
(37452, 'Daniel 11:29', 'Daniel', 11, 29, 'په مقرر وخت به هغه بيا په جنوبى مُلک حمله وکړى، خو دې ځل به يې نتيجه د مخکښې نه بدله وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_29.mp3', '', 1761754199, 1761754199),
(37453, 'Daniel 11:30', 'Daniel', 11, 30, 'د مغربى سمندر د غاړې کشتۍ به د هغۀ مخالف راشى، او هغه به زړۀ بائيلى. بيا به هغه واپس شى او خپله غصه به د مقدس لوظ په خلقو وباسى. هغه به واپس شى او په هغوئ به مهربان شى څوک چې مقدس لوظ هېروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_30.mp3', '', 1761754199, 1761754199),
(37454, 'Daniel 11:31', 'Daniel', 11, 31, 'د هغۀ لښکر به راشى چې د عبادتګاه بې‌حرمتى وکړى او روزانه قربانۍ به بندې کړى. هغوئ به هلته هغه ناپاکه بُت ودروى کوم چې به تباهى راولى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_31.mp3', '', 1761754199, 1761754199),
(37455, 'Daniel 11:32', 'Daniel', 11, 32, 'بادشاه به په غوړو خبرو سره هغوئ دوکه کړى چا چې لوظ مات کړے دے، خو کوم خلق چې خپل خُدائ پاک پېژنى هغوئ به زورَور وى او د هغۀ مقابله به وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_32.mp3', '', 1761754199, 1761754199),
(37456, 'Daniel 11:33', 'Daniel', 11, 33, 'څوک چې هوښيار دى هغوئ به ډېرو ته صحيح تعليم ورکړى، خو د څۀ وخت دپاره به هغوئ په تُوره قتل کړے شى يا به وسوزولے شى يا به قېد کړے شى او يا به لوټ کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_33.mp3', '', 1761754199, 1761754199),
(37457, 'Daniel 11:34', 'Daniel', 11, 34, 'کله چې هغوئ راپرېوځى ورته به صرف لږ مدد مِلاو شى، او ډېر چې مخلص نۀ دى ورسره به ملګرى شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_34.mp3', '', 1761754199, 1761754199),
(37458, 'Daniel 11:35', 'Daniel', 11, 35, 'څۀ هوښياران به قتل کړے شى، د دې دپاره چې د آخر وخت پورې صفا، خالص او بې‌داغه کړے شى ځکه چې مقرر وخت راتلونکے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_35.mp3', '', 1761754199, 1761754199),
(37459, 'Daniel 11:36', 'Daniel', 11, 36, 'بادشاه به هغه څۀ کوى څۀ چې يې زړۀ غواړى. هغه به خپل ځان د هر معبود نه اوچت او لوئ ګڼى او د خُدائ پاک خلاف به هم کُفر وائى څوک چې د ټولو معبودانو خُدائ پاک دے. هغه به کامياب شى تر هغه وخته چې د غضب وخت پوره شوے نۀ وى، ځکه څۀ چې وئيلے شوى دى هغه به پوره کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_36.mp3', '', 1761754199, 1761754199),
(37460, 'Daniel 11:37', 'Daniel', 11, 37, 'هغه به د خپل پلار نيکۀ معبودانو له عزت نۀ ورکوى او نۀ هغه معبود له کوم چې د ښځو خوښ دے، او نۀ به د يو معبود عزت کوى، خو هغه به خپل ځان د دې ټولو نه اوچت ګڼى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_37.mp3', '', 1761754199, 1761754199),
(37461, 'Daniel 11:38', 'Daniel', 11, 38, 'د دې په ځائ به هغه د قلعه ګانو د معبود عزت وکړى، د هغه معبود کوم چې د دۀ پلار نيکۀ نۀ پېژندلو. هغه به د هغۀ عزت د سرو او سپينو زرو او قيمتى کاڼو او قيمتى تُحفو ورکولو سره وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_38.mp3', '', 1761754199, 1761754199),
(37462, 'Daniel 11:39', 'Daniel', 11, 39, 'هغه به د پردى معبود په مدد سره په مضبوطو قلعه ګانو حمله وکړى او د هغوئ به ډېر عزت کوى څوک چې د هغۀ حکومت منى. هغه به هغوئ په ډېرو خلقو حکمرانان مقرر کړى او په اجر کښې به په هغوئ زمکه تقسيم کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_39.mp3', '', 1761754199, 1761754199),
(37463, 'Daniel 11:40', 'Daniel', 11, 40, 'په آخر وخت کښې به د جنوب بادشاه هغۀ سره په جنګ شى، او د شمال بادشاه به د هغۀ خلاف د جنګى ګا‌ډو او آسونو سوارو او ډېرو سمندرى کشتو سره راوځى. هغه به په ډېرو مُلکونو حمله وکړى او هغوئ به لکه د سېلاب غوندې ختم کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_40.mp3', '', 1761754199, 1761754199),
(37464, 'Daniel 11:41', 'Daniel', 11, 41, 'هغه به په ښائسته مُلک حمله وکړى. ډېر مُلکونه به شکست وخورى، خو ادوم، موآب او د عمون مشران به د هغۀ د لاس نه بچ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_41.mp3', '', 1761754199, 1761754199),
(37465, 'Daniel 11:42', 'Daniel', 11, 42, 'هغه به خپل حکومت په ډېرو مُلکونو ومنى، او مِصر به ترې هم خلاص نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_42.mp3', '', 1761754199, 1761754199),
(37466, 'Daniel 11:43', 'Daniel', 11, 43, 'هغه به د مِصر د سرو او سپينو خزانې او ټول دولت قبضه کړى، او ليبيا او ايتهوپيا به هم هغۀ ته تسليم شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_43.mp3', '', 1761754199, 1761754199),
(37467, 'Daniel 11:44', 'Daniel', 11, 44, 'خو بيا به د مشرق او شمال افواګانې هغه پرېشانه کړى، او هغه به په ډېره غصه کښې راوځى چې ډېر خلق تباه او نيست و نابود کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_44.mp3', '', 1761754199, 1761754199),
(37468, 'Daniel 11:45', 'Daniel', 11, 45, 'هغه به شاهى خېمې د سمندر او د ښائسته مقدس غرۀ په مينځ کښې ولګوى. بيا هم به د هغۀ خاتمه راشى، او هيڅ څوک به د هغۀ مدد نۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel11_verse_45.mp3', '', 1761754199, 1761754199),
(37469, 'Isaiah 36:1', 'Isaiah', 36, 1, 'د حزقیا د پاچاهۍ په څوارلسم کال د اشور پاچا سنخاریب د یهودا په ټولو قوي شویو ښارونو باندې حمله وکړه او هغه یې ونیول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_1.mp3', '', 1761754199, 1761754199),
(37470, 'Isaiah 36:2', 'Isaiah', 36, 2, 'د اشور پاچا یو لوی لښکر د خپل لوړ رتبه مامور سره د لاکیش څخه ولېږه چې په اورشلیم کې د حزقیا مخالفت وکړي. هغه د پاسني ډنډ د لښتي په غاړه چې د کالیو وینځونکو د پټي په لاره کې پرته ده، ودرېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_2.mp3', '', 1761754199, 1761754199),
(37471, 'Isaiah 36:3', 'Isaiah', 36, 3, 'د حزقیا پاچا درې درباریان دباندې راووتل چې د هغوی سره لیدنه کتنه وکړي. هغه درباریان دا وو: د حلقیا زوی الیاقیم چې د ماڼۍ مسوول ؤ، شبنا د دربار منشي او د اساف زوی یواخ چې د پېښو د ثبتولو مسوول ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_3.mp3', '', 1761754199, 1761754199),
(37472, 'Isaiah 36:4', 'Isaiah', 36, 4, 'د اشوریانو لوړ رتبه ملکي مامور هغوی ته وویل: «لوی پاچا یعنې د اشور پاچا غواړي په دې پوه شي چې حزقیا پاچا په څه شي باندې تکیه کوي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_4.mp3', '', 1761754199, 1761754199),
(37473, 'Isaiah 36:5', 'Isaiah', 36, 5, 'خپل پاچا ته ووایئ: ‹ایا ته فکر کوې چې یوازې خبرې کولای شي چې د عسکري پوهې او قدرت ځای ونیسي؟ ته په چا باندې تکیه کوې چې زما په وړاندې یاغي شوی یې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_5.mp3', '', 1761754199, 1761754199),
(37474, 'Isaiah 36:6', 'Isaiah', 36, 6, 'ګوره، ته په دې تمه یې چې مصر به درسره مرسته وکړي، خو هغه به د هغې کړکي په شان وي چې د امسا په توګه ورڅخه کار اخیستل کیږي. هغه به مات شي، ستا په لاس کې به ننوځي او تا به ټپي کړي. نو هرڅوک چې د مصر په پاچا باندې تکیه وکړي هغه به همداسې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_6.mp3', '', 1761754199, 1761754199),
(37475, 'Isaiah 36:7', 'Isaiah', 36, 7, 'کېدای شي ماته ووایئ چې مونږ په خپل څښتن خدای باندې تکیه کوو. ایا دا هغه څوک نه دی چې حزقیا د هغه د عبادت او د قربانۍ ځایونه له منځه یووړل او د یهودا او اورشلیم خلکو ته یې وویل چې تاسو د دې قرباني ځای په وړاندې چې په اورشلیم کې دی عبادت وکړئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_7.mp3', '', 1761754199, 1761754199),
(37476, 'Isaiah 36:8', 'Isaiah', 36, 8, 'زه به ستاسو سره د خپل بادار، یعنې د اشور د پاچا په استازیتوب یو شرط کېږدم. زه به تاسو ته دوه زره اسونه درکړم، خو که چېرې تاسو وکولای شئ چې همدومره کسان پیدا کړئ چې په هغو باندې سپاره شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_8.mp3', '', 1761754199, 1761754199),
(37477, 'Isaiah 36:9', 'Isaiah', 36, 9, 'تاسو د جنګي ګاډیو او سپرو عسکرو په خاطر په مصر باندې تکیه کوئ. نو څنګه کولای شئ چې تاسو زما د بادار د خدمتګارانو څخه حتی یو ډېر کمزوری منصبدار په شا وتمبوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_9.mp3', '', 1761754199, 1761754199),
(37478, 'Isaiah 36:10', 'Isaiah', 36, 10, 'ایا تاسو فکر کوئ چې ما د څښتن د مرستې څخه پرته ستاسو په وطن باندې حمله کړې ده چې هغه وران کړم؟ څښتن په خپله ماته وویل چې په هغه باندې حمله وکړم او هغه له منځه یوسم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_10.mp3', '', 1761754199, 1761754199),
(37479, 'Isaiah 36:11', 'Isaiah', 36, 11, 'په دې وخت کې الیاقیم، شبنا او یوآخ هغه لوړ رتبه مامور ته وویل: «مهرباني وکړئ، زمونږ سره د آرامۍ په ژبه خبرې وکړئ، ځکه چې مونږ په هغې باندې پوهېږو. د یهودا په ژبه خبرې مه کوئ، ځکه هغه ټول خلک چې په دېوال باندې ناست دي ستاسو خبرو ته یې غوږ ایښی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_11.mp3', '', 1761754199, 1761754199),
(37480, 'Isaiah 36:12', 'Isaiah', 36, 12, 'هغه لوړ رتبه مامور ځواب ورکړ: «ایا تاسو فکر کوئ چې زما پاچا زه د دې دپاره رالېږلی یم چې دا ټولې خبرې یوازې تاسو او ستاسو پاچا ته وکړم؟ نه، زه د هغو خلکو سره هم خبرې کوم چې په دېوال باندې ناست دي. هغوی او تاسو به دومره وږي او تږي شئ چې خپل غایطه مواد به وخوري او خپلې متیازې به وڅښئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_12.mp3', '', 1761754199, 1761754199),
(37481, 'Isaiah 36:13', 'Isaiah', 36, 13, 'بیا هغه مامور ودرېده او په لوړ اواز یې د یهودا په ژبه وویل: «د اشوریانو د لوی پاچا پیغام واورئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_13.mp3', '', 1761754199, 1761754199),
(37482, 'Isaiah 36:14', 'Isaiah', 36, 14, 'پاچا داسې وایي: ‹حزقیا مه پرېږدئ چې تاسو وغولوي. هغه نه شي کولای چې تاسو وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_14.mp3', '', 1761754199, 1761754199),
(37483, 'Isaiah 36:15', 'Isaiah', 36, 15, 'باور مه کوئ که هغه تاسو ته ووایي: په څښتن باندې تکیه وکړئ. هغه به تاسې وژغوري او دا ښار به د اشور پاچا ته په لاس ورنه کړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_15.mp3', '', 1761754199, 1761754199),
(37484, 'Isaiah 36:16', 'Isaiah', 36, 16, 'د حزقیا خبرو ته غوږ مه نیسئ، ځکه چې د اشور پاچا داسې وایي: زما سره روغه جوړه وکړئ. راووځئ او ماته تسلیم شئ. نو تاسو هر یو به د خپلو تاکونو انګور وخورئ، د خپلو ونو څخه به انځر وخورئ او د خپلو ذخیرو څخه به اوبه وڅښئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_16.mp3', '', 1761754199, 1761754199),
(37485, 'Isaiah 36:17', 'Isaiah', 36, 17, 'وروسته زه راځم او تاسو به هغه هېواد ته بوځم چې ستاسو د وطن په شان دی. په هغه هېواد کې چې د شرابو د جوړولو دپاره د انګورو باغونه او د ډوډۍ د دپاره غلې دانې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_17.mp3', '', 1761754199, 1761754199),
(37486, 'Isaiah 36:18', 'Isaiah', 36, 18, 'پام وکړئ داسې نه چې حزقیا تاسو بې لارې کړي او تاسو ته ووایي چې څښتن به تاسو وژغوري. ایا کله د کوم قوم خدایانو خپل وطن د اشور پاچا له لاسه ژغورلی دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_18.mp3', '', 1761754199, 1761754199),
(37487, 'Isaiah 36:19', 'Isaiah', 36, 19, 'چېرته دي د حمات او ارفاد خدایان؟ چېرته دي د سفروایم خدایان؟ ایا هغوی سامره زما د لاسونو څخه وژغورله؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_19.mp3', '', 1761754199, 1761754199),
(37488, 'Isaiah 36:20', 'Isaiah', 36, 20, 'د دې ټولو هېوادونو د خدایانو څخه کوم یو دا توان درلود چې خپل هېواد زما څخه وژغوري؟ نو څښتن به څنګه وکولای شي چې اورشلیم زما د لاسونو څخه خلاص کړي؟›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_20.mp3', '', 1761754199, 1761754199),
(37489, 'Isaiah 36:21', 'Isaiah', 36, 21, 'خو خلک غلي پاتې شول او په ځواب کې یې ورته هېڅ ونه ویل، ځکه چې حزقیا پاچا هغوی ته دا امر کړی ؤ چې ځواب ورنه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_21.mp3', '', 1761754199, 1761754199),
(37490, 'Isaiah 36:22', 'Isaiah', 36, 22, 'نو الیاقیم، شبنا او یواخ له غمه خپل کالي وشکول، حزقیا ته ورغلل او څه چې هغه مامور ورته ویلي وو، هغه یې ورته بیان کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah36_verse_22.mp3', '', 1761754199, 1761754199),
(37491, 'Isaiah 6:1', 'Isaiah', 6, 1, 'په کوم کال چې عزیا پاچا مړ شو، ما څښتن ولید چې هغه په ډېر لوړ تخت باندې ناست ؤ. ټول د عبادت ځای د هغه د چپنې په لمن باندې ډک شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_1.mp3', '', 1761754199, 1761754199),
(37492, 'Isaiah 6:2', 'Isaiah', 6, 2, 'د هغه دپاسه الوتونکي اسماني موجودات ولاړ وو او هر یو یې شپږ شپږ وزرونه لرل. په دوه وزرو باندې یې خپل مخونه پټ کړي وو، په دوه وزرونو یې خپل بدن پټ کړی ؤ او له دوه وزرونو څخه یې د الوتلو دپاره کار اخیست.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_2.mp3', '', 1761754199, 1761754199),
(37493, 'Isaiah 6:3', 'Isaiah', 6, 3, 'هغوی په وار سره دا ویل او یو بل ته به یې غږ کاوه: «سپېڅلی، سپېڅلی! سپېڅلی دی مطلق قادر څښتن! ډکه ده نړۍ ټوله د هغه د جلال نه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_3.mp3', '', 1761754199, 1761754199),
(37494, 'Isaiah 6:4', 'Isaiah', 6, 4, 'د هغوی د اوازونو د شور له لاسه د عبادت د ځای بنیاد ولړزېد او د عبادت ځای د لوګي څخه ډک شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_4.mp3', '', 1761754199, 1761754199),
(37495, 'Isaiah 6:5', 'Isaiah', 6, 5, 'ما وویل: «افسوس زما په حال! زما دپاره نوره کومه هیله نشته، ځکه زما د ژبې نه چې هر ټکی راوځي هغه له ګناه نه ډک دی او زه د داسې خلکو په منځ کې اوسېږم چې د هغوی هره خبره له ګناه ډکه ده. خو ما په خپلو سترګو پاچا یعنې مطلق قادر څښتن لیدلی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_5.mp3', '', 1761754199, 1761754199),
(37496, 'Isaiah 6:6', 'Isaiah', 6, 6, 'بیا یو اسماني موجود د قربانۍ له ځایه د پلتې پاکوونکو په وسیله یوه سره سکروټه راواخیستله او زما خواته راوالوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_6.mp3', '', 1761754199, 1761754199),
(37497, 'Isaiah 6:7', 'Isaiah', 6, 7, 'هغه په سرې سکروټې زما شونډې لمس کړې او ویې ویل: «وګوره، دا سکروټه ستا په شونډو باندې لګېدلې ده او اوس ستا ګناه پاکه او جرم دې بخښل شوی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_7.mp3', '', 1761754199, 1761754199),
(37498, 'Isaiah 6:8', 'Isaiah', 6, 8, 'بیا مې د څښتن اواز واورېد چې پوښتنه کوي: «څوک ولېږم؟ څوک دې ته تیار دی چې زمونږ پیغام خلکو ته ورسوي؟» ما ورته په ځواب کې وویل: «زه حاضر یم! ما ولېږه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_8.mp3', '', 1761754199, 1761754199),
(37499, 'Isaiah 6:9', 'Isaiah', 6, 9, 'نو څښتن ماته وویل: «لاړ شه او دې خلکو ته دا پیغام ورسوه: ‹تاسو که هرڅومره واورئ، پوه به نه شئ. که هرڅومره وګورئ، لیدلی به یې نه شئ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_9.mp3', '', 1761754199, 1761754199),
(37500, 'Isaiah 6:10', 'Isaiah', 6, 10, 'د دې خلکو زړونه سخت کړه، د هغوی غوږونه کاڼه کړه او سترګې یې ړندې کړه چې ونه وویني، غوږونه یې وانه وري او په زړونو کې پوه نه شي. که چېرې هغوی داسې وکړل، نو کېدای شي چې ماته راوګرځي او شفا ومومي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_10.mp3', '', 1761754199, 1761754199),
(37501, 'Isaiah 6:11', 'Isaiah', 6, 11, 'ما پوښتنه وکړه: «ای څښتنه، ترڅو پورې به داسې وي؟» هغه ځواب راکړ: «تر هغې پورې چې ښارونه وران، کورونه خالي او ځمکه شاړه او ویجاړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_11.mp3', '', 1761754199, 1761754199),
(37502, 'Isaiah 6:12', 'Isaiah', 6, 12, 'زه به هغه خلک لېرې ولېږم او ټول وطن به وران او ویجاړ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_12.mp3', '', 1761754199, 1761754199),
(37503, 'Isaiah 6:13', 'Isaiah', 6, 13, 'حتی که په هغه وطن کې د لسو کسانو څخه یو پاتې شي، نو هغه به هم له منځه لاړ شي. هغه به د څېړۍ د ونو په شان وي چې پرې کیږي او تنه یې پاتې کیږي.» بیا د دې تنې څخه سپېڅلی قوم راپیدا کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah6_verse_13.mp3', '', 1761754199, 1761754199),
(37504, 'Numbers 34:1', 'Numbers', 34, 1, 'څښتن موسی ته وویل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_1.mp3', '', 1761754199, 1761754199),
(37505, 'Numbers 34:2', 'Numbers', 34, 2, 'چې د اسراییلو قوم ته داسې حکم وکړي: «کله چې تاسو د کنعان خاورې ته ورننوځئ، یعنې هغې خاورې ته چې تاسو ته یې درکوم، نو ستاسو سیمه به دغه سرحدونه ولري:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_2.mp3', '', 1761754199, 1761754199),
(37506, 'Numbers 34:3', 'Numbers', 34, 3, 'جنوبي سرحد به د صین دښته او د ادوم شمال لوېدیځ سرحد وي. دا سرحد به د مړې بحیرې په جنوبي اخرني سر کې پیل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_3.mp3', '', 1761754199, 1761754199),
(37507, 'Numbers 34:4', 'Numbers', 34, 4, 'د هغه ځای څخه به هغه د لوېدیځ خواته ورسیږي، خو د جنوب خواته به وروګرځي چې د عقربیم غاښی، د صین کلی او د قادش برنیع ښار په کې شامل شي. د هغه ځای څخه به دا سرحد حصرادار او عصمون ته ورسیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_4.mp3', '', 1761754199, 1761754199),
(37508, 'Numbers 34:5', 'Numbers', 34, 5, 'چې د هغه خوړ په لوري به وروګرځي چې د مصر په سرحد کې دی او د مدیترانې په بحیره کې به ختم شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_5.mp3', '', 1761754199, 1761754199),
(37509, 'Numbers 34:6', 'Numbers', 34, 6, 'د مدیترانې بحیره به لوېدیځ سرحد وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_6.mp3', '', 1761754199, 1761754199),
(37510, 'Numbers 34:7', 'Numbers', 34, 7, 'شمالي سرحد به د مدیترانې په بحیره کې پیل شي بیا به د ختیځ په لور د هور غره ته ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_7.mp3', '', 1761754199, 1761754199);